import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.stream.IntStream;

public class Prim {
    public static void main(String[] args) {
        OptionalInt mx = IntStream.of(3, 9, 6).filter(x -> x > 5).max();
        OptionalDouble avg = IntStream.of(3, 9, 6).average();
        System.out.println(mx.getAsInt() + " " + avg.getAsDouble());
    }
}

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        List<Integer> list = new ArrayList<>(List.of(1, 2, 3, 4, 5));

        list.parallelStream()
            .map(x -> x * 2)
            .forEachOrdered(System.out::println);
    }
}

import java.util.*;

public class Reduce {
    public static void main(String[] args) {
        List<Integer> list = List.of(1, 2, 3, 4, 5);
        int a = list.stream().reduce(10, Integer::sum);
        int b = list.parallelStream().reduce(10, Integer::sum);
        System.out.println(a);
        System.out.println(b);
    }
}
